// Handling 429 politely:
async function politeFetch(url) {
  const res = await fetch(url);
  if (res.status === 429) {
    const seconds = Number(res.headers.get("Retry-After")) || 5;
    throw new Error("Too many requests. Try again in " + seconds + "s.");
  }
  return res;
}

