  const visible = useMemo(
    () => items.filter((i) => i.title.toLowerCase().includes(filter.toLowerCase())),
    [items, filter],
  );

  const toggle = useCallback(
    (id) => setItems((list) => list.map((i) => (i.id === id ? { ...i, done: !i.done } : i))),
    [setItems],
  );

  return (
