export function useMyNotes(uid) {
  const [notes, setNotes] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!uid) return;
    const q = query(
      collection(db, "notes"),
      where("owner", "==", uid),
      orderBy("createdAt", "desc"),
      limit(20),
    );
    return onSnapshot(
      q,
      (snap) => setNotes(snap.docs.map((d) => ({ id: d.id, ...d.data() }))),
      (err) => setError(err.message),
    );
  }, [uid]);

  return { notes, error };
}

