// O(n²): includes scans 'other' for every item in 'list'.
// O(n): build a Set once, then each lookup is O(1).
function countShared(list, other) {
  const set = new Set(other);
  let count = 0;
  for (const a of list) if (set.has(a)) count++;
  return count;
}
